globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"british-bulldog","year":2023,"grade":"3-4","contest":"British Bulldog","letters":"ABCD","count":30,"language":"en","points":3,"tasksFile":"3-4/tasks.pdf","answersFile":"reviewed-3-4.pdf","listeningFile":"3-4/listening.mp3","titleLanguage":"en","sections":[{"start":1,"title":"Listening"},{"start":6,"title":"The bundle of sticks"},{"start":11,"title":"Grammar"},{"start":16,"title":"Odd word out"},{"start":21,"title":"Parts of the body"},{"start":26,"title":"A day at the beach"}],"reviewedKey":true}, [{"title":"The Man’s Destination","question":"Where does the man want to go?","choices":["To London","To the platform 5","To Oxford","To Bath"],"answer":2,"steps":["Ищи место после слов «the next train to …». Оно также повторяется, когда мужчина просит билеты.","Он спрашивает о поезде to Oxford, то есть до Оксфорда."],"context":"Listen to the dialogue and answer the questions.","audio":true},{"title":"How He Is Travelling","question":"How is the man going to get there?","choices":["By tram","By plane","By train","By bus"],"answer":2,"steps":["В вопросе How спрашивают, каким транспортом он собирается ехать. Слушай название транспорта в первой части разговора.","Мужчина спрашивает о train. By train означает «на поезде»."],"context":"Listen to the dialogue and answer the questions.","audio":true},{"title":"The Platform Number","question":"What is the number of the platform?","choices":["10","1","2","3"],"answer":3,"steps":["В записи называют время отправления 10:30, а затем номер платформы. Ищи число сразу после platform.","Звучит «platform three». Поезд отправляется с третьей платформы."],"context":"Listen to the dialogue and answer the questions.","audio":true},{"title":"At the Ticket Counter","question":"What does the man want to buy?","choices":["Ice-cream","Tickets","Books","Toys"],"answer":1,"steps":["«I’d like …, please» — вежливый способ попросить что-либо. Послушай, что мужчина называет в этой фразе.","Он говорит «I’d like three tickets to Oxford, please». Tickets значит «билеты»."],"context":"Listen to the dialogue and answer the questions.","audio":true},{"title":"How Much He Pays","question":"How much does the man pay?","choices":["3 pounds","10 pounds","30 pounds","33 pounds"],"answer":2,"steps":["Сравни число билетов и сумму оплаты. Цена звучит в ответе на просьбу о трёх билетах.","Кассир отвечает «That’s thirty pounds». Всего мужчина платит 30 фунтов."],"context":"Listen to the dialogue and answer the questions.","audio":true},{"title":"The Father’s Character","question":"What kind of man was the father?","choices":["Wise","Stupid","Brave","Silly"],"answer":0,"steps":["Текст начинается словами «a clever man», а в конце перед его обращением к сыновьям есть ещё одно описание.","В рассказе его называют the wise father. Wise означает «мудрый»."],"context":"Read the text and answer the questions.\n\nThere once lived a clever man with three sons. He loved them very much, but he was sorry that they often quarrelled. One day he wanted to teach them a lesson. He showed his sons a bundle of sticks and asked them to break the bundle in half. The youngest son put the bundle across his knee but couldn’t break it. The middle son put the sticks on the ground and wanted to break them with his hands. The oldest son took the ends of the bundle in each hand and tried to split it in half in front of him, but also with no result. Then their father untied the bundle and gave one stick to each son. The sons easily broke the sticks in half. “My sons”, said the wise father, “each of you alone is as weak as one of these sticks. But if you all stand together, nobody will be able to break you”."},{"title":"Why the Father Worried","question":"Why was the man often worried? Because his sons ... a lot.","choices":["walked","worked","argued","played"],"answer":2,"steps":["В первых предложениях отец переживает из-за того, что сыновья often quarrelled. Узнай значение глагола quarrel.","Quarrel значит «ссориться». Ближайший по смыслу вариант argued — «спорили»."],"context":"Read the text and answer the questions.\n\nThere once lived a clever man with three sons. He loved them very much, but he was sorry that they often quarrelled. One day he wanted to teach them a lesson. He showed his sons a bundle of sticks and asked them to break the bundle in half. The youngest son put the bundle across his knee but couldn’t break it. The middle son put the sticks on the ground and wanted to break them with his hands. The oldest son took the ends of the bundle in each hand and tried to split it in half in front of him, but also with no result. Then their father untied the bundle and gave one stick to each son. The sons easily broke the sticks in half. “My sons”, said the wise father, “each of you alone is as weak as one of these sticks. But if you all stand together, nobody will be able to break you”."},{"title":"The Father’s Lesson","question":"What did the father want his sons to learn? To ... .","choices":["read books","do homework","do exercises","stick together"],"answer":3,"steps":["По одному прутья легко сломать. Когда отец связал их вместе, сыновья не смогли сломать весь пучок.","На этом примере отец объяснил, что вместе братья сильнее. Stick together означает «держаться вместе»."],"context":"Read the text and answer the questions.\n\nThere once lived a clever man with three sons. He loved them very much, but he was sorry that they often quarrelled. One day he wanted to teach them a lesson. He showed his sons a bundle of sticks and asked them to break the bundle in half. The youngest son put the bundle across his knee but couldn’t break it. The middle son put the sticks on the ground and wanted to break them with his hands. The oldest son took the ends of the bundle in each hand and tried to split it in half in front of him, but also with no result. Then their father untied the bundle and gave one stick to each son. The sons easily broke the sticks in half. “My sons”, said the wise father, “each of you alone is as weak as one of these sticks. But if you all stand together, nobody will be able to break you”.","reviewedEdition":true},{"title":"What He Did to the Bundle","question":"What did the boys’ father do with the sticks? He ... the sticks.","choices":["unfastened","cut","decorated","burnt"],"answer":0,"steps":["После попыток сыновей отец untied the bundle. Bundle — связка, а untie означает «развязать».","Подходит unfastened — «рассоединил, развязал». Он дал каждому сыну по одному пруту."],"context":"Read the text and answer the questions.\n\nThere once lived a clever man with three sons. He loved them very much, but he was sorry that they often quarrelled. One day he wanted to teach them a lesson. He showed his sons a bundle of sticks and asked them to break the bundle in half. The youngest son put the bundle across his knee but couldn’t break it. The middle son put the sticks on the ground and wanted to break them with his hands. The oldest son took the ends of the bundle in each hand and tried to split it in half in front of him, but also with no result. Then their father untied the bundle and gave one stick to each son. The sons easily broke the sticks in half. “My sons”, said the wise father, “each of you alone is as weak as one of these sticks. But if you all stand together, nobody will be able to break you”."},{"title":"What He Hoped For","question":"What did the man want his sons to do in the future? To ... each other.","choices":["fight with","hate","quarrel with","help and support"],"answer":3,"steps":["Прочитай обращение отца в конце. Он объясняет, что вместе сыновья будут сильнее.","Он хочет, чтобы сыновья помогали и поддерживали друг друга. Это help and support each other."],"context":"Read the text and answer the questions.\n\nThere once lived a clever man with three sons. He loved them very much, but he was sorry that they often quarrelled. One day he wanted to teach them a lesson. He showed his sons a bundle of sticks and asked them to break the bundle in half. The youngest son put the bundle across his knee but couldn’t break it. The middle son put the sticks on the ground and wanted to break them with his hands. The oldest son took the ends of the bundle in each hand and tried to split it in half in front of him, but also with no result. Then their father untied the bundle and gave one stick to each son. The sons easily broke the sticks in half. “My sons”, said the wise father, “each of you alone is as weak as one of these sticks. But if you all stand together, nobody will be able to break you”."},{"title":"The Teacher’s Instructions","question":"He didn’t listen ... the teacher’s instructions.","choices":["to","with","at","–"],"answer":0,"steps":["Listen означает «слушать». Перед тем, кого или что слушают, употребляется определённый предлог.","Нужен to: listen to the teacher’s instructions — «слушать указания учителя»."],"context":"Fill in the blanks."},{"title":"Whose Cat?","question":"Whose cat is this?","choices":["It’s my","It’s mine","It’s me","It’s our"],"answer":1,"steps":["Whose спрашивает, кому принадлежит кот. В ответе слово cat не повторяется, поэтому нужно самостоятельное притяжательное местоимение.","Mine означает «мой» и может стоять без существительного. My требовало бы слова cat после себя."],"context":"Fill in the blanks."},{"title":"The First Lesson","question":"What time ... the first lesson start?","choices":["is","do","does","has"],"answer":2,"steps":["Подлежащее the first lesson в единственном числе. В вопросе о расписании используется Present Simple.","С таким подлежащим берём does. Основной глагол остаётся start, потому что -s уже выражено формой does."],"context":"Fill in the blanks.","reviewedEdition":true},{"title":"What the Men Enjoy","question":"What ... the men like to do?","choices":["do","does","is","are"],"answer":0,"steps":["Men — множественное число от man. Для вопроса о привычках или предпочтениях выбираем форму do или does.","Со множественным числом ставим do: «What do the men like to do?»."],"context":"Fill in the blanks."},{"title":"Television Habits","question":"Do you like ... TV?","choices":["watch","to look","looking","watching"],"answer":3,"steps":["Для просмотра телевизора используется сочетание watch TV. После like нам нужна форма, которая входит в это предложение целиком.","Подходит watching: like watching TV означает «любить смотреть телевизор»."],"context":"Fill in the blanks."},{"title":"Clothes and Footwear","question":"Which word is different?","choices":["Skirt","Shirt","Jumper","Sneakers"],"answer":3,"steps":["Skirt, shirt и jumper — юбка, рубашка и джемпер. Все эти предметы надевают на туловище или талию.","Sneakers — кроссовки, то есть обувь. Это лишнее слово в таком наборе."]},{"title":"Toys and School Things","question":"Which word is different?","choices":["Puppet","Rattle","School bag","Yo-yo"],"answer":2,"steps":["Puppet, rattle и yo-yo — кукла, погремушка и йо-йо. Их используют для игры.","School bag — школьная сумка. Она нужна для учебных принадлежностей, поэтому отличается от трёх игрушек."]},{"title":"Types of Animals","question":"Which word is different?","choices":["Pig","Bear","Cow","Horse"],"answer":1,"steps":["Pig, cow и horse — свинья, корова и лошадь. Этих животных обычно можно увидеть на ферме.","Bear — медведь. В этом наборе он выделяется как дикое животное."]},{"title":"Fruit and Berries","question":"Which word is different?","choices":["Pear","Gooseberry","Strawberry","Blackcurrant"],"answer":0,"steps":["Gooseberry — крыжовник, strawberry — клубника, blackcurrant — чёрная смородина. В кулинарии их обычно относят к ягодам.","Pear означает «груша». Она отличается от трёх ягод из списка."]},{"title":"Furniture and Tools","question":"Which word is different?","choices":["Cupboard","Stool","Wardrobe","Broom"],"answer":3,"steps":["Cupboard, stool и wardrobe — шкаф, табурет и платяной шкаф. Все три относятся к мебели.","Broom означает «метла». Это предмет для уборки, поэтому он лишний."]},{"title":"The Upper Left Arrow","question":"This is his ... .","choices":["cheek","forehead","chin","eye brows"],"answer":0,"steps":["Проследи стрелку от номера 21. Она заканчивается сбоку от рта и ниже глаза.","Это щека, cheek. Forehead находится над глазами, а chin — под ртом."],"context":"What is this?","figure":{"src":"assets/british-bulldog/2023/3-4/arrows.webp","alt":"Five arrows point to parts of the boy’s head or body. Number 21 points below and to the side of an eye, number 22 between the head and shoulders, number 23 above the eyebrows, number 24 at the line of the mouth, and number 25 directly beneath the mouth.","width":622,"height":621,"detailSrc":"assets/british-bulldog/2023/3-4/arrows.svg"}},{"title":"The Lower Left Arrow","question":"This is his ... .","choices":["neck","forehead","chin","eye brows"],"answer":0,"steps":["Номер 22 соединён стрелкой с частью тела между головой и плечами.","Это шея, neck. Chin означает подбородок, который расположен выше."],"context":"What is this?","figure":{"src":"assets/british-bulldog/2023/3-4/arrows.webp","alt":"Five arrows point to parts of the boy’s head or body. Number 21 points below and to the side of an eye, number 22 between the head and shoulders, number 23 above the eyebrows, number 24 at the line of the mouth, and number 25 directly beneath the mouth.","width":622,"height":621,"detailSrc":"assets/british-bulldog/2023/3-4/arrows.svg"}},{"title":"The Upper Right Arrow","question":"This is his ... .","choices":["lips","forehead","neck","chin"],"answer":1,"steps":["Стрелка 23 направлена к участку над бровями и под волосами.","Этот участок называется forehead — лоб. Lips — губы, chin — подбородок."],"context":"What is this?","figure":{"src":"assets/british-bulldog/2023/3-4/arrows.webp","alt":"Five arrows point to parts of the boy’s head or body. Number 21 points below and to the side of an eye, number 22 between the head and shoulders, number 23 above the eyebrows, number 24 at the line of the mouth, and number 25 directly beneath the mouth.","width":622,"height":621,"detailSrc":"assets/british-bulldog/2023/3-4/arrows.svg"}},{"title":"The Middle Right Arrow","question":"These are his ... .","choices":["neck","cheeks","chin","lips"],"answer":3,"steps":["Стрелка 24 заканчивается там, где нарисована линия улыбки. These are показывает, что ответ во множественном числе.","Lips означает «губы». Cheeks — щёки по сторонам рта, а стрелка указывает на сам рот."],"context":"What is this?","figure":{"src":"assets/british-bulldog/2023/3-4/arrows.webp","alt":"Five arrows point to parts of the boy’s head or body. Number 21 points below and to the side of an eye, number 22 between the head and shoulders, number 23 above the eyebrows, number 24 at the line of the mouth, and number 25 directly beneath the mouth.","width":622,"height":621,"detailSrc":"assets/british-bulldog/2023/3-4/arrows.svg"}},{"title":"The Lower Right Arrow","question":"This is his ... .","choices":["cheek","chin","neck","eye brows"],"answer":1,"steps":["Проследи стрелку от числа 25. Она касается нижней части лица сразу под ртом.","Это подбородок, chin. Neck — шея ниже него."],"context":"What is this?","figure":{"src":"assets/british-bulldog/2023/3-4/arrows.webp","alt":"Five arrows point to parts of the boy’s head or body. Number 21 points below and to the side of an eye, number 22 between the head and shoulders, number 23 above the eyebrows, number 24 at the line of the mouth, and number 25 directly beneath the mouth.","width":622,"height":621,"detailSrc":"assets/british-bulldog/2023/3-4/arrows.svg"}},{"title":"Where the Children Are","question":"Where are the children?","choices":["In the forest","Near the pool","On the beach","In the mountains"],"answer":2,"steps":["На рисунке дети находятся на песке, рядом видны море и волны. Ищи название такого места.","Это пляж — on the beach. Near the pool означает «рядом с бассейном»."],"context":"Look at the picture and find the correct answers.","figure":{"src":"assets/british-bulldog/2023/3-4/children.webp","alt":"Children play on sand beside waves. At left a boy sits by a sand structure with towers. A child nearer the water holds a line attached to a kite. A girl in a pink hat with blue petals sits in sunlight on a towel. At right a child holds a small loop near his mouth with round transparent shapes floating nearby.","width":652,"height":437}},{"title":"The Girl with the Hat","question":"What is the girl with the hat on her head doing? She is ... .","choices":["sleeping","flying the kite","sunbathing","building a castle"],"answer":2,"steps":["Найди девочку в розовой шляпе. Она расположилась на полотенце под солнцем, а воздушного змея держит другой ребёнок.","Sunbathing означает «загорает». Этому соответствует её поза на пляже."],"context":"Look at the picture and find the correct answers.","figure":{"src":"assets/british-bulldog/2023/3-4/children.webp","alt":"Children play on sand beside waves. At left a boy sits by a sand structure with towers. A child nearer the water holds a line attached to a kite. A girl in a pink hat with blue petals sits in sunlight on a towel. At right a child holds a small loop near his mouth with round transparent shapes floating nearby.","width":652,"height":437}},{"title":"The Hat Decoration","question":"What is her hat decorated with?","choices":["A leaf","A butterfly","A branch","A flower"],"answer":3,"steps":["Рассмотри синее украшение на розовой шляпе. У него несколько лепестков вокруг центральной части.","Это цветок — a flower. Leaf означает один лист, а branch — ветка."],"context":"Look at the picture and find the correct answers.","figure":{"src":"assets/british-bulldog/2023/3-4/children.webp","alt":"Children play on sand beside waves. At left a boy sits by a sand structure with towers. A child nearer the water holds a line attached to a kite. A girl in a pink hat with blue petals sits in sunlight on a towel. At right a child holds a small loop near his mouth with round transparent shapes floating nearby.","width":652,"height":437}},{"title":"The Child on the Right","question":"What is the child standing on the right doing? He is ... .","choices":["building a castle","swimming in the sea","making bubbles","flying the kite"],"answer":2,"steps":["Посмотри, что ребёнок справа держит возле рта и какие круглые шарики летят рядом.","Он пускает мыльные пузыри. В английском здесь подходит making bubbles."],"context":"Look at the picture and find the correct answers.","figure":{"src":"assets/british-bulldog/2023/3-4/children.webp","alt":"Children play on sand beside waves. At left a boy sits by a sand structure with towers. A child nearer the water holds a line attached to a kite. A girl in a pink hat with blue petals sits in sunlight on a towel. At right a child holds a small loop near his mouth with round transparent shapes floating nearby.","width":652,"height":437}},{"title":"The Boy on the Left","question":"What is the boy on the left doing? He is ... .","choices":["sunbathing","building a castle","swimming","flying the kite"],"answer":1,"steps":["Посмотри на мальчика в левой части картинки. Он сидит на песке рядом с башенками, формочками и лопаткой.","Он строит песчаный замок. Это building a castle."],"context":"Look at the picture and find the correct answers.","figure":{"src":"assets/british-bulldog/2023/3-4/children.webp","alt":"Children play on sand beside waves. At left a boy sits by a sand structure with towers. A child nearer the water holds a line attached to a kite. A girl in a pink hat with blue petals sits in sunlight on a towel. At right a child holds a small loop near his mouth with round transparent shapes floating nearby.","width":652,"height":437}}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
